from pathlib import Path
import json,hashlib
r=Path(__file__).resolve().parent.parent
base=json.loads((r/'verification_regression_R10_on_R11.json').read_text());assert base['total_fresh_simulation_runs']==126
names=['irq_r11','irq_unit_r11','return_guard_r11','no_diag_r11','timing_platform','timing_legacy','cdc_r11_5','exsp_work_r11_2','msx_request_r11_3','slot_r11_4','write_r11_9','sd_r11_9']
parts={n:json.loads((r/('verification_'+n+'_result.json')).read_text()) for n in names};counts={n:j.get('fresh_runs',j.get('runs',0)) for n,j in parts.items()}
assert counts==dict(irq_r11=41,irq_unit_r11=18,return_guard_r11=17,no_diag_r11=4,timing_platform=3,timing_legacy=4,cdc_r11_5=9,exsp_work_r11_2=12,msx_request_r11_3=2,slot_r11_4=0,write_r11_9=4,sd_r11_9=8),counts
paths=[p for p in (r/'fpga').rglob('*') if p.is_file()]+list((r/'hardware_test').glob('*.COM'))
j=dict(series='restart R11.9',purpose='R11.7 CPU baseline; SD read register index captured alongside SD select',major_function_stage=7,timing_work_stage=10,R10_compatible_regression_runs=126,new_runs=counts,total_fresh_simulation_runs=126+sum(counts.values()),expected_failure_runs=base['expected_failure_runs']+sum(parts[n]['expected_failure_runs'] for n in ['cdc_r11_5','msx_request_r11_3','slot_r11_4','write_r11_9','sd_r11_9']),all_cases_executed_this_revision=True,verification_scope='CPU/bridge/controller regression, request-register and actual slot RTL tests; full top not simulated',PC_bits=24,SPS_bits=16,SPL_bits=24,I_bits=16,ADL_reset=0,preloaded_20_COM_unchanged=True,separate_16_and_24_bit_buses=True,MSX_extended_access_isolation=True,diagnostic_vector_read_only=True,diagnostic_writes_remain_MSX=True,diagnostic_intent_held_through_WAIT_and_CEN_pause=True,msx_request_checks_per_profile=86016,SDRAM_request_first_sample_edge='falling clk_108m',SDRAM_qualified_payload_minimum_cycles_after_request=3,SDRAM_pending_minimum_cycles_after_request=3.5,SDRAM_payload_stable_until_ack_verified=True,SDC_CST_GPRJ_CPU_bridge_wrapper_and_SDRAM_unchanged=True,SD_read_index_registered_with_select=True,CPU_baseline="R11.7",VDP_unchanged=True,no_new_or_relaxed_timing_exceptions=True,native_ADL_IM1_IM2_NMI_RETI_RETN=True,MBASE_MADL_mixed_frames_implemented=False,R11_8_user_report=json.loads((r/'doc/R11_8_GOWIN_BASELINE.json').read_text()),R11_7_user_report=json.loads((r/'doc/R11_7_GOWIN_BASELINE.json').read_text()),R11_6_user_report=json.loads((r/'doc/R11_6_GOWIN_BASELINE.json').read_text()),R11_5_user_report=json.loads((r/'doc/R11_5_GOWIN_BASELINE.json').read_text()),R11_4B_user_report=json.loads((r/'doc/R11_4B_GOWIN_BASELINE.json').read_text()),GOWIN_run_for_this_revision=False,hardware_run_for_this_revision=False,timing_closure_for_this_revision=False,area_for_this_revision_measured=False,PR1014_resolution_unverified=True,full_MSX_DOS_BIOS_simulated=False,sha256={str(p.relative_to(r)):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths})
